def npc(name, role, where, play, wants, secret, reacts, lines, extra=None):
    """One character card: how to play them, what they want and hide, how they react, and their lines."""
    out = [('h2', name), ('p', f'<i>{role}</i>'),
           ('kv', [('Usually found', where), ('How to play them', play), ('What they want', wants), ('What they hide', secret)]),
           ('ifs', reacts)]
    for who, line in lines:
        out.append(('say', who, line))
    if extra:
        out += extra
    return out


